# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DİKDÖRTGENLER PRİZMASININ HACİM BAĞINTISI (V = a · b · c)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Birim Küplerden Hacim Formülüne</text>\n  <polygon points="70,185 170,185 205,155 105,155" fill="#93c5fd" stroke="#1d4ed8" stroke-width="1.5"/>\n  <rect x="70" y="115" width="100" height="70" fill="#bfdbfe" fill-opacity="0.85" stroke="#1d4ed8" stroke-width="1.5"/>\n  <polygon points="70,115 170,115 205,85 105,85" fill="#dbeafe" stroke="#1d4ed8" stroke-width="1.5"/>\n  <polygon points="170,115 205,85 205,155 170,185" fill="#60a5fa" stroke="#1d4ed8" stroke-width="1.5"/>\n  <text x="120" y="202" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">a = 5 br (Boy)</text>\n  <text x="218" y="176" font-size="11.5" font-weight="bold" fill="#1e40af">b = 3 br (En)</text>\n  <text x="52" y="152" text-anchor="end" font-size="11.5" font-weight="bold" fill="#1e40af">c = 4 br</text>\n  <text x="235" y="105" font-size="11" fill="#334155">• 1 Katman = 5 × 3 = 15 küp</text>\n  <text x="235" y="127" font-size="11" fill="#334155">• 4 Katman = 15 × 4 = 60 küp</text>\n  <text x="235" y="152" font-size="11.5" font-weight="bold" fill="#1d4ed8">V = Taban Alanı × Yükseklik</text>\n  <text x="235" y="172" font-size="11.5" font-weight="bold" fill="#1d4ed8">V = (a · b) · c = 60 br³</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Özel Prizmaların Hacim Bağıntıları</text>\n  <text x="378" y="102" font-size="11.5" font-weight="bold" fill="#166534">1. Dikdörtgenler Prizması (a, b, c):</text>\n  <text x="390" y="120" font-size="11" fill="#334155">V = Taban Alanı × Yükseklik = a · b · c</text>\n  <text x="378" y="148" font-size="11.5" font-weight="bold" fill="#166534">2. Kare Prizma (Taban ayrıtı a, yükseklik c):</text>\n  <text x="390" y="166" font-size="11" fill="#334155">V = a · a · c = a² · c</text>\n  <text x="378" y="194" font-size="11.5" font-weight="bold" fill="#166534">3. Küp (Tüm ayrıtları eşit: a = b = c):</text>\n  <text x="390" y="212" font-size="11" fill="#334155">V = a · a · a = a³</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">STANDART HACİM ÖLÇME BİRİMLERİ BASAMAĞI (BİNDE BİR / BİN KATI)</text>\n  <rect x="25" y="48" width="330" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="190" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Hacim Birimleri Merdiveni (×1000 / ÷1000)</text>\n  <rect x="45" y="84" width="90" height="28" rx="5" fill="#1d4ed8"/>\n  <text x="90" y="103" text-anchor="middle" font-size="12" font-weight="bold" fill="#ffffff">m³ (Metreküp)</text>\n  <rect x="110" y="120" width="95" height="28" rx="5" fill="#2563eb"/>\n  <text x="157" y="139" text-anchor="middle" font-size="12" font-weight="bold" fill="#ffffff">dm³ (Desimetre)</text>\n  <rect x="175" y="156" width="95" height="28" rx="5" fill="#3b82f6"/>\n  <text x="222" y="175" text-anchor="middle" font-size="12" font-weight="bold" fill="#ffffff">cm³ (Santimetre)</text>\n  <rect x="240" y="192" width="95" height="28" rx="5" fill="#60a5fa"/>\n  <text x="287" y="211" text-anchor="middle" font-size="12" font-weight="bold" fill="#ffffff">mm³ (Milimetre)</text>\n  <text x="275" y="102" font-size="11" font-weight="bold" fill="#15803d">Aşağı her adım: × 1000</text>\n  <text x="50" y="212" font-size="11" font-weight="bold" fill="#b91c1c">Yukarı her adım: ÷ 1000</text>\n  <rect x="375" y="48" width="300" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="525" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Temel Birim Dönüşüm Eşitlikleri</text>\n  <text x="392" y="100" font-size="11.5" font-weight="bold" fill="#92400e">• 1 m³ = 1 000 dm³ = 1 000 000 cm³</text>\n  <text x="392" y="126" font-size="11.5" font-weight="bold" fill="#92400e">• 1 dm³ = 1 000 cm³ = 1 000 000 mm³</text>\n  <text x="392" y="152" font-size="11.5" font-weight="bold" fill="#92400e">• 1 cm³ = 1 000 mm³</text>\n  <text x="392" y="180" font-size="11" fill="#334155">• 4,5 m³ = 4,5 × 1000 = 4 500 dm³</text>\n  <text x="392" y="202" font-size="11" fill="#334155">• 75 000 cm³ = 75 000 ÷ 1000 = 75 dm³</text>\n  <text x="392" y="224" font-size="11" fill="#334155">• 2 400 mm³ = 2 400 ÷ 1000 = 2,4 cm³</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HACİM VE SIVI ÖLÇME BİRİMLERİ ARASINDAKİ KÖPRÜ (1 dm³ = 1 L)</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Sıvı Ölçme Birimleri (10\'ar Kat)</text>\n  <text x="45" y="100" font-size="11.5" font-weight="bold" fill="#166534">L (Litre) → dL (Desilitre) → cL (Santilitre) → mL</text>\n  <text x="45" y="124" font-size="11" fill="#334155">• Aşağı her basamak × 10, yukarı ÷ 10</text>\n  <text x="45" y="148" font-size="11.5" fill="#334155">• 1 L = 10 dL = 100 cL = 1 000 mL</text>\n  <text x="45" y="172" font-size="11.5" fill="#334155">• 1 dL = 10 cL = 100 mL</text>\n  <text x="45" y="196" font-size="11.5" fill="#334155">• 1 cL = 10 mL</text>\n  <text x="45" y="220" font-size="11" font-weight="bold" fill="#15803d">Örnek: 2,5 L = 25 dL = 250 cL = 2 500 mL</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Hacim — Sıvı Ölçüsü Köprü Eşitlikleri</text>\n  <text x="380" y="104" font-size="12" font-weight="bold" fill="#991b1b">1. Altın Köprü: 1 dm³ = 1 L (Litre)</text>\n  <text x="390" y="124" font-size="11" fill="#334155">Kenarı 1 dm (10 cm) olan küp 1 L su alır.</text>\n  <text x="380" y="154" font-size="12" font-weight="bold" fill="#991b1b">2. Küçük Köprü: 1 cm³ = 1 mL (Mililitre)</text>\n  <text x="390" y="174" font-size="11" fill="#334155">Çünkü 1 dm³ = 1000 cm³ ve 1 L = 1000 mL\'dir.</text>\n  <text x="380" y="204" font-size="12" font-weight="bold" fill="#991b1b">3. Büyük Köprü: 1 m³ = 1 000 dm³ = 1 000 L</text>\n  <text x="390" y="222" font-size="11" fill="#334155">1 metreküp su deposu tam 1 000 litre su alır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
